(function () {
  "use strict";

  function escapeHtml(text) {
    return String(text)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function readGroup(input, start) {
    var depth = 0;
    var body = "";
    for (var i = start; i < input.length; i += 1) {
      var ch = input.charAt(i);
      if (ch === "{") {
        if (depth > 0) body += ch;
        depth += 1;
      } else if (ch === "}") {
        depth -= 1;
        if (depth === 0) return { body: body, end: i + 1 };
        body += ch;
      } else {
        body += ch;
      }
    }
    return null;
  }

  function replaceCommandGroups(input, command, renderer) {
    var token = "\\" + command;
    var output = "";
    var index = 0;
    while (index < input.length) {
      var found = input.indexOf(token, index);
      if (found < 0) {
        output += input.slice(index);
        break;
      }
      output += input.slice(index, found);
      var first = readGroup(input, found + token.length);
      if (!first) {
        output += token;
        index = found + token.length;
        continue;
      }
      var second = command === "frac" ? readGroup(input, first.end) : null;
      if (command === "frac" && !second) {
        output += token + "{" + first.body + "}";
        index = first.end;
        continue;
      }
      output += renderer(first.body, second ? second.body : "");
      index = second ? second.end : first.end;
    }
    return output;
  }

  function renderLatex(input) {
    var html = escapeHtml(input || "");
    html = html
      .replace(/\\left/g, "")
      .replace(/\\right/g, "")
      .replace(/\\,/g, " ")
      .replace(/\\;/g, " ")
      .replace(/\\!/g, "")
      .replace(/\\sum/g, "∑")
      .replace(/\\times/g, "×")
      .replace(/\\cdot/g, "·")
      .replace(/\\pm/g, "±")
      .replace(/\\mp/g, "∓")
      .replace(/\\leq/g, "≤")
      .replace(/\\geq/g, "≥")
      .replace(/\\neq/g, "≠")
      .replace(/\\approx/g, "≈")
      .replace(/\\infty/g, "∞")
      .replace(/\\rightarrow/g, "→")
      .replace(/\\to/g, "→")
      .replace(/\\Omega/g, "Ω")
      .replace(/\\Delta/g, "Δ")
      .replace(/\\Sigma/g, "Σ")
      .replace(/\\alpha/g, "α")
      .replace(/\\beta/g, "β")
      .replace(/\\gamma/g, "γ")
      .replace(/\\delta/g, "δ")
      .replace(/\\theta/g, "θ")
      .replace(/\\lambda/g, "λ")
      .replace(/\\mu/g, "μ")
      .replace(/\\pi/g, "π")
      .replace(/\\sigma/g, "σ")
      .replace(/\\phi/g, "φ")
      .replace(/\\omega/g, "ω");

    html = replaceCommandGroups(html, "text", function (body) { return body; });
    html = replaceCommandGroups(html, "tag", function (body) {
      return '<span class="katex-tag">(' + escapeHtml(body) + ")</span>";
    });
    html = replaceCommandGroups(html, "sqrt", function (body) {
      return '<span class="katex-sqrt">' + renderLatex(body) + "</span>";
    });
    var previous = "";
    while (previous !== html) {
      previous = html;
      html = replaceCommandGroups(html, "frac", function (num, den) {
        return '<span class="katex-frac"><span class="katex-frac-num">' +
          renderLatex(num) + '</span><span class="katex-frac-den">' +
          renderLatex(den) + "</span></span>";
      });
    }

    html = html.replace(/_\{([^{}]+)\}|_([A-Za-z0-9]+)/g, function (_, grouped, plain) {
      return "<sub>" + renderLatex(grouped || plain) + "</sub>";
    });
    html = html.replace(/\^\{([^{}]+)\}|\^([A-Za-z0-9+\-]+)/g, function (_, grouped, plain) {
      return "<sup>" + renderLatex(grouped || plain) + "</sup>";
    });
    html = html.replace(/[{}]/g, "");
    return '<span class="katex">' + html + "</span>";
  }

  window.katex = {
    renderToString: function (expression, options) {
      try {
        return renderLatex(expression);
      } catch (error) {
        if (options && options.throwOnError) throw error;
        return '<span class="katex katex-error">' + escapeHtml(expression) + "</span>";
      }
    }
  };
}());
